import ezdxf, glob
for f in sorted(glob.glob('drawings/*.dxf')):
    doc = ezdxf.readfile(f)
    msp = doc.modelspace()
    print('====================', f, '====================')
    for e in msp:
        if e.dxftype() in ('TEXT','MTEXT','ATTRIB','ATTDEF'):
            try:
                t = e.dxf.text if e.dxftype()=='TEXT' else e.text
            except Exception:
                t = ''
            t = t.replace('\n',' | ')
            if t.strip():
                try:
                    p = e.dxf.insert if e.dxftype()=='TEXT' else e.dxf.insert
                    print(f'  [{p[0]:.1f},{p[1]:.1f}] {t}')
                except Exception:
                    print('  ', t)
